style.css:
@-moz-document domain("youtube.com") {
/* === YouTube Progress Bar with Running GIF === */

  /* Make the progress bar container stable */
  .ytp-progress-bar-container {
    position: relative !important;
    height: 6px !important;
    overflow: visible !important;
    z-index: 9999 !important;
  }

  /* Style the main progress part */
  .ytp-play-progress {
    background: linear-gradient(90deg, #c2a3ff, #e3d8f5) !important;
    height: 6px !important;
    position: relative !important;
    border-radius: 3px !important;
    transition: width 0.05s linear !important;
    overflow: visible !important;
  }

  /* Add the GIF as a moving icon on the right edge */
  .ytp-play-progress::after {
    content: "";
    position: absolute !important;
    top: -18px !important;
    right: -13px !important; /* positions gif correctly at edge */
    width: 32px !important;
    height: 32px !important;
    background: url("https://media.tenor.com/rtxrNbNxDaEAAAAi/running-run.gif") center/contain no-repeat !important;
    pointer-events: none !important;
    z-index: 999999 !important;
    animation: bob 0.6s ease-in-out infinite alternate !important;
  }

  /* little bounce animation for style */
  @keyframes bob {
    from { transform: translateY(0); }
    to { transform: translateY(-3px); }
  }
}
